  'chat.workStatus.telemetry.responseSpeed': 'Ответ',
  'chat.workStatus.telemetry.responseSpeedDescription': 'Как быстро пришёл финальный текст. Не учитывает начальное ожидание, рассуждения и предыдущие вызовы инструментов. Оценка по временным меткам текста, а не измерение скорости провайдером.',
  'chat.workStatus.telemetry.speed': 'Весь ход',
  'chat.workStatus.telemetry.speedDescription': 'Сгенерированные токены по всем шагам, включая рассуждения, делённые на время без учёта работы инструментов. Ожидание модели учитывается, поэтому много коротких вызовов инструментов может снизить это значение.',
  'chat.workStatus.telemetry.elapsed': 'Затрачено',
  'chat.workStatus.telemetry.elapsedDescription': 'Время по часам от первого сообщения пользователя до финального ответа ассистента. Включает ожидание модели, работу инструментов, компактификацию и другие промежутки.',
  'chat.workStatus.telemetry.llmDuration': 'Время модели',
  'chat.workStatus.telemetry.llmDurationDescription': 'Время на все шаги модели, включая ожидание ответов. Время работы инструментов исключено. Это не только время генерации текста.',
  'chat.workStatus.telemetry.toolDuration': 'Инструменты',
  'chat.workStatus.telemetry.toolDurationDescription': 'Время выполнения инструментов, включая неудачные вызовы. Инструменты, работавшие одновременно, считаются один раз, а не суммируются.',
  'chat.workStatus.telemetry.ttft': 'Средний TTFT',
  'chat.workStatus.telemetry.ttftDescription': 'Среднее ожидание до начала первого текста или рассуждения в каждом шаге модели. Скрыто, если у шага нет начала после создания — это обычно для шагов только с инструментами и для частей, помеченных временем создания.',
  'chat.workStatus.telemetry.firstOutput': 'Первый вывод',
  'chat.workStatus.telemetry.firstOutputDescription': 'Среднее ожидание от начала каждого шага модели до первого, что модель отправляет: текст, рассуждение или вызов инструмента. В отличие от TTFT, шаги, начинающиеся с вызова инструмента, тоже учитываются. Скрыто для шагов из OpenCode старше 2.3.0.',
  'chat.workStatus.telemetry.steps': 'Шаги',
  'chat.workStatus.telemetry.stepsDescription': 'Сколько раз модель вызывалась для этого промпта. Чтение результатов инструментов и решение, что делать дальше, обычно требуют ещё одного шага.',
