  'chat.workStatus.telemetry.cacheHit': 'Кэш',
  'chat.workStatus.telemetry.cacheHitDescription': 'Доля входных токенов, переиспользованных из кэша промпта по всем шагам. Переиспользование контекста снижает стоимость и ожидание, но это не оценка скорости.',
  'chat.workStatus.telemetry.cost': 'Стоимость',
